t key and retaining latches are visible; one latch remains open.","description":"DIMM slot"},{"id":"atx_power_port","label":"24-pin ATX power header","imageAsset":null,"inspection":"The 24-pin ATX header is keyed and clear of debris. It must remain de-energized during inspection.","description":"24-pin ATX power header"}],"component":"tap_inspect","equipment":{"completion":[{"path":"inspected.motherboard","value":true},{"path":"inspected.cpu","value":true},{"path":"inspected.ram","value":true},{"path":"inspected.psu","value":true},{"path":"inspected.cpu_socket","value":true},{"path":"inspected.dimm_slot","value":true},{"path":"inspected.atx_power_port","value":true}],"single_connection":true},"mechanics":["inspect_hardware"]},"availableObjectIds":["motherboard","cpu","ram","psu","cpu_socket","dimm_slot","atx_power_port","anti_static_strap"],"primaryInteraction":"inspect","supportingInteractions":[]},{"id":"coc1_m1_p2","title":"Select a safe set","feedbackIds":["coc1_m1_constraint"],"instruction":"Record the components and safety equipment needed for the work.","presentation":{"options":[{"id":"esd_protection","label":"Wrist strap — ESD protection"},{"id":"open_memory_latch","label":"Memory latch requires attention"},{"id":"service_live","label":"Service while energized"}],"component":"multi_select","equipment":{"tools":[{"id":"anti_static_strap","label":"Anti-static wrist strap","compatible_categories":["esd_ground"]},{"id":"screwdriver","label":"Phillips screwdriver","compatible_categories":["fastener"]}],"targets":[{"id":"chassis_ground","label":"Bare chassis ground point","category":"esd_ground"},{"id":"case_fastener","label":"Case fastener","category":"fastener"}],"completion":[{"path":"selection.coc1_m1_p2","operator":"present"},{"path":"classification.processing","operator":"present"},{"path":"classification.memory","operator":"present"},{"path":"classification.power","operator":"present"},{"path":"tool.chassis_ground","value":"anti_static_strap"},{"path":"too