true},{"path":"inspected.dimm_slot","value":true},{"path":"inspected.atx_power_port","value":true}],"counts":"step:coc1_m1_p1"},{"id":"classification","fault":"At least one component role conflicts with the inspected specification.","label":"Component roles","nominal":"Processing, volatile memory, and power-conversion components classified.","requires":[{"path":"classification.processing","value":["cpu"],"operator":"set_equals"},{"path":"classification.memory","value":["ram"],"operator":"set_equals"},{"path":"classification.power","value":["psu"],"operator":"set_equals"}],"counts":"step:coc1_m1_p2"},{"id":"safe_work","fault":"The work plan omits an observed hazard or permits energized servicing.","label":"Safe work plan","nominal":"ESD controls and the unseated memory latch are recorded.","requires":[{"path":"selection.coc1_m1_p2","value":["esd_protection","open_memory_latch"],"operator":"set_equals"}],"counts":"safety:coc1_m1_p2"},{"id":"notes","fault":"No inspection notes recorded.","label":"Observation record","nominal":"Inspection notes attached.","requires":[{"path":"observation.coc1_m1_p3","operator":"present"}],"counts":"step:coc1_m1_p3"},{"id":"close_out","fault":"Complete safety close-out and the service report before final verification.","label":"Safety and documentation","nominal":"Work-area safety, contingency where required, and service handover recorded.","requires":[{"path":"setting.work_area_safe","value":true},{"path":"setting.service_report_ready","value":true}],"counts":"step:coc1_m1_p4"}],"completion":[{"path":"result.coc1_m1_test_4","value":true}],"operations":[{"id":"close_work_area","label":"Record 5S and 3Rs work-area close-out","effects":{"work_area_safe":true},"requires":[]},{"id":"prepare_service_report","label":"Prepare the technical work report for handover","effects":{"service_report_ready":true},"requires":[{"path":"setting.work_area_safe","value":true}]}],"single_connection":true},"mechanics":["verify_readiness"],"evidenceActionType":"hardware_readiness_test"},"availableObjectIds":["motherboard","cpu","ram","psu","cpu_socket","dimm_slot","atx_power_port","anti_static_strap"],"primaryInteraction":"testRun","supportingInteractions":[]},{"id":"coc1_m1_p5","title":"Review evidence","feedbackIds":["coc1_m1_review"],"instruction":"Review the safe-set decision and readiness evidence.","presentation":{"equipment":{"single_connection":true},"mechanics":["review_evidence"]},"availableObjectIds":["motherboard","cpu","ram","psu","cpu_socket","dimm_slot","atx_power_port","anti_static_strap"],"primaryInteraction":"review","supportingInteractions":[]}],"scenario":"Inspect a de-energized desktop before servicing. The memory latch is open. Identify component roles, isolate abnormalities, and record a safe work plan.","reviewMetadata":{"title":"Evidence review","returnLabel":"Return to mission","confirmLabel":"Confirm evidence"},"feedbackCatalog":{"coc1_m1_review":"Review the inspection, safety selection, and observation evidence before submission.","coc1_m1_evidence":"Readiness verification records the observed hardware state.","coc1_m1_constraint":"Inspect the component label and safety condition before recording the set."},"environmentLabel":"Hardware inspection bench","practiceGuidance":"Inspect labels and visible conditions before recording any decision.","interactionFamilies":["inspect","select","observe","testRun"]},"contract_version":"css-sag-20261109-v3","scoring_method":"binary_sum","competency_method":"all_required","threshold_rule":"Each step allows at most two incorrect attempts: refused actions, corrections, confirmed wrong orders and, once per failed final verification test, a failing check of the state the step owns. Safety-critical steps (ESD, PPE, power isolation) allow none.","client_score_authoritative":false}'),
