en interpret the result.","presentation":{"target":"coc1_m2_post","component":"test_with_interpretation","equipment":{"checks":[{"id":"psu_mounting","fault":"Pre-power inspection: the power supply moves in its bay. Its screws are not fastened.","label":"Power-supply mounting","counts":"step:psu","nominal":"Power supply fastened in its bay.","requires":[{"path":"setting.psu_fastened","value":true}]},{"id":"board_mounting","fault":"Pre-power inspection: the motherboard moves on its standoffs. Its screws are not fastened.","label":"Motherboard mounting","counts":"step:board","nominal":"Motherboard fastened on its standoffs.","requires":[{"path":"setting.board_fastened","value":true}]},{"id":"drive_mounting","fault":"Pre-power inspection: the drive moves in its bay. Its screws are not fastened.","label":"Drive mounting","counts":"step:drive","nominal":"Drive fastened in its bay.","requires":[{"path":"setting.drive_fastened","value":true}]},{"id":"power_switch","fault":"No power-on: pressing the case power button does nothing. The front-panel switch is not connected to F_PANEL.","label":"Power button","counts":"step:data_cables","nominal":"The case power button starts the system; the power LED lights.","requires":[{"path":"link.front_panel>board_front_panel","value":true}]},{"id":"cpu_power","fault":"No POST — CPU power not detected. Fans spin but the CPU debug LED stays lit.","label":"CPU power","counts":"step:power_cables","nominal":"8-pin EPS CPU power present.","requires":[{"path":"link.eps_8pin>board_eps8","value":true}]},{"id":"cpu_detection","fault":"No POST — CPU debug LED lit. The processor is not held against the socket contacts.","label":"Processor detection","counts":"step:cpu","nominal":"Processor detected.","requires":[{"path":"setting.cpu_lever","value":"closed"}]},{"id":"cpu_fan","fault":"CPU fan error — the CPU_FAN header reports 0 RPM.","label":"CPU fan","counts":"step:cooling","nominal":"CPU_FAN reports 1450 RPM.","requires":[{"path":"link.cooler_fan>cpu_fan_header","value":true}]},{"id":"cpu_temperature","fault":"CPU over-temperature warning — 96 °C within 20 seconds of power-on.","label":"CPU temperature","counts":"step:cooling","nominal":"CPU temperature stable at 38 °C.","repairs":["item:cooler"],"requires":[{"path":"setting.thermal_compound","value":true}]},{"id":"memory_detection","fault":"Memory not detected — DRAM debug LED lit and the board repeats its memory beep code.","label":"Memory detection","counts":"step:memory","nominal":"16 GB DDR4 detected.","requires":[{"path":"setting.dimm_latches","value":"closed"}]},{"id":"memory_channels","fault":"Memory running in single-channel mode — the modules are not in the DIMM_A2 and DIMM_B2 slots the board manual specifies for two modules.","label":"Memory configuration","counts":"step:memory","nominal":"Dual-channel mode: modules in DIMM_A2 and DIMM_B2 as the board manual specifies.","requires":[{"path":"placed.ram_1","value":["dimm_a2","dimm_b2"],"operator":"one_of"},{"path":"placed.ram_2","value":["dimm_a2","dimm_b2"],"operator":"one_of"}]},{"id":"drive_power","fault":"No boot device found — the drive does not spin up. SATA power is not connected.","label":"Drive power","counts":"step:power_cables","nominal":"The drive spins up.","requires":[{"path":"link.sata_power>drive_power","value":true}]},{"id":"boot_device","fault":"No boot device found — the drive spins but is not detected. The SATA data cable is not connected.","label":"Boot device","counts":"step:data_cables","nominal":"SATA drive detected on port 0; ready to boot installation media.","requires":[{"path":"link.sata_data>drive_data","value":true}]}],"placement":{"items":[{"id":"cooler","label":"CPU cooler","category":"cpu_cooler","requires":[{"path":"placed.cpu","operator":"present"}]},{"id":"ram_1","label":"Memory module 1","category":"ddr4_dimm","requires":[{"path":"setting.dimm_latches","value":"open"}],"orientations":["0","90","180","270"],"initial_orientation":"180","seating_orientation":"0"},{"i