e CPU socket lever","effects":{"cpu_lever":"closed"},"requires":[{"path":"setting.cpu_lever","value":"open"}]},{"id":"apply_thermal_compound","label":"Apply thermal compound to the CPU","effects":{"thermal_compound":true},"requires":[{"path":"placed.cpu","operator":"present"},{"path":"placed.cooler","value":[null],"operator":"one_of"}]},{"id":"open_dimm_latches","label":"Open the DIMM latches","effects":{"dimm_latches":"open"},"requires":[{"path":"setting.dimm_latches","value":[null,"closed"],"operator":"one_of"}]},{"id":"close_dimm_latches","label":"Lock the DIMM latches","effects":{"dimm_latches":"closed"},"requires":[{"path":"setting.dimm_latches","value":"open"}]},{"id":"pick_screwdriver","label":"Pick up the Phillips screwdriver","effects":{"hand_tool":"screwdriver"},"requires":[]},{"id":"fasten_psu","label":"Fasten the power-supply screws","effects":{"psu_fastened":true},"requires":[{"path":"placed.psu","operator":"present"},{"path":"setting.hand_tool","value":"screwdriver"}]},{"id":"fasten_motherboard","label":"Fasten the motherboard screws","effects":{"board_fastened":true},"requires":[{"path":"placed.motherboard","operator":"present"},{"path":"setting.hand_tool","value":"screwdriver"}]},{"id":"fasten_drive","label":"Fasten the drive screws","effects":{"drive_fastened":true},"requires":[{"path":"placed.storage","operator":"present"},{"path":"setting.hand_tool","value":"screwdriver"}]}],"single_connection":true},"mechanics":["power_on_self_test"],"bench_steps":[{"id":"run_post","done":[{"path":"tested.coc1_m2_post","operator":"present"}],"focus":{"id":"test-run-start","kind":"controls"},"label":"Power on and run the POST"},{"id":"clear_faults","done":[{"path":"result.coc1_m2_post","value":true}],"focus":{"id":"test-run-start","kind":"controls"},"label":"Correct each reported fault on the bench, then run the POST again"},{"id":"interpret","done":[{"path":"interpretation.coc1_m2_p5","operator":"present"}],"focus":{"id":"test-interpretation-coc1_m2_p5","kind":"c