('coc1_m3', 'Install and Configure a Workstation OS — simulation assessment', '[{"criterion_code":"COC1_M3_S1","title":"Inspect and configure setup","description":"Place the equipment in the workspace, then complete the inspection and work-order checks. The boot console reports a blank GPT disk and UEFI media. Configure firmware and select the installation target.","source_trace":"LO1.2 Install operating system and drivers for peripherals/devices · PC 1.5, 2.1, 3.1 · TR Computer Systems Servicing NC II (Amended December 2013); ByteQuest supplementary simulation assessment, not an official TESDA certification.","evidence_rule":{"operator":"simulation_condition","phase_ids":["coc1_m3_p1"],"conditions":[{"path":"placed.system_unit","operator":"present"},{"path":"placed.boot_usb","operator":"present"}],"counted_targets":["phase:coc1_m3_p1","item:system_unit","item:boot_usb","step:coc1_m3_p1"],"max_incorrect":2},"scoring_rule":{"status":"APPROVED","method":"binary","satisfied_value":1,"not_satisfied_value":0,"classification":"TECHNICAL_BINARY_ENCODING","note":"1/0 encodes SATISFIED/NOT SATISFIED only; it is not a TESDA percentage or criterion weight."},"max_value":1,"order_index":1,"is_required":true},{"criterion_code":"COC1_M3_S2","title":"Install the operating system","description":"Sequence the installation operations before applying them.","source_trace":"LO1.2 Install operating system and drivers for peripherals/devices · PC 1.5, 2.1, 3.1 · TR Computer Systems Servicing NC II (Amended December 2013); ByteQuest supplementary simulation assessment, not an official TESDA certification.","evidence_rule":{"operator":"simulation_condition","phase_ids":["coc1_m3_p2"],"conditions":[{"path":"operation.install_os","value":true}],"counted_targets":["phase:coc1_m3_p2","operation:install_os","operation:prepare_boot_media","step:coc1_m3_p2"],"max_incorrect":2},"scoring_rule":{"status":"APPROVED","method":"binary","satisfied_value":1,"not_satisfied_value":0,"classification":"TECHN