 service status","reveals_fact_id":"service_status_fact"},{"id":"inspect_access_scope","label":"Inspect access scope","reveals_fact_id":"access_scope_fact"}]},"availableObjectIds":["client","server","service","network_path","permission_scope"],"primaryInteraction":"troubleshoot","supportingInteractions":[]},{"id":"coc3_m5_p4","title":"Correct fault","feedbackIds":["coc3_m5_constraint"],"instruction":"Apply the correction supported by the earned facts.","presentation":{"choices":[{"id":"restore_support_membership","label":"Restore the authorized technician to the Support group","equipment_effects":{"authorized_access":true}},{"id":"restart_service","label":"Restart the running file service","equipment_effects":{"authorized_access":false}},{"id":"grant_everyone","label":"Grant Modify to all users","equipment_effects":{"authorized_access":false}}],"component":"scenario_decision","equipment":{"single_connection":true},"mechanics":["correct_fault"]},"availableObjectIds":["client","server","service","network_path","permission_scope"],"primaryInteraction":"decide","supportingInteractions":[]},{"id":"coc3_m5_p5","title":"Retest recovery","feedbackIds":["coc3_m5_evidence"],"instruction":"Run client access and service recovery checks.","presentation":{"target":"retest_service_access","equipment":{"checks":[{"id":"authorization","fault":"Requested least-privilege access is not restored.","label":"Client write request","nominal":"Authorized technician can modify; Learners remain read-only.","requires":[{"path":"setting.authorized_access","value":true}],"counts":"step:coc3_m5_p4"},{"id":"close_out","fault":"Complete safety close-out and the service report before final verification.","label":"Safety and documentation","nominal":"Work-area safety, contingency where required, and service handover recorded.","requires":[{"path":"setting.work_area_safe","value":true},{"path":"setting.service_report_ready","value":true}],"counts":"step:coc3_m5_p5"}],"completion":[{"path":"result.retest_service_access","value":true}],"operations":[{"id":"close_work_area","label":"Record 5S and 3Rs work-area close-out","effects":{"work_area_safe":true},"requires":[]},{"id":"prepare_service_report","label":"Prepare the technical work report for handover","effects":{"service_report_ready":true},"requires":[{"path":"setting.work_area_safe","value":true}]}],"single_connection":true},"mechanics":["retest_recovery"],"evidenceActionType":"retest_requested"},"availableObjectIds":["client","server","service","network_path","permission_scope"],"primaryInteraction":"testRun","supportingInteractions":[]},{"id":"coc3_m5_p6","title":"Review evidence","feedbackIds":["coc3_m5_review"],"instruction":"Review inspection, diagnostics, correction, and recovery evidence.","presentation":{"equipment":{"single_connection":true},"mechanics":["review_evidence"]},"availableObjectIds":["client","server","service","network_path","permission_scope"],"primaryInteraction":"review","supportingInteractions":[]}],"scenario":"A client loses access to a previously available server resource.","reviewMetadata":{"title":"Evidence review","returnLabel":"Return to mission","confirmLabel":"Confirm evidence"},"feedbackCatalog":{"coc3_m5_review":"Review the earned facts, correction, retest, and recovery state.","coc3_m5_evidence":"Recovery verification must follow the selected corrective action.","coc3_m5_constraint":"Inspect client, server, service, network, and permission facts progressively."},"environmentLabel":"Client-server recovery console","practiceGuidance":"Inspect each layer progressively and unlock correction only after earning facts.","interactionFamilies":["troubleshoot","decide","testRun"]},"contract_version":"css-sag-20261011-v2","scoring_method":"binary_sum","competency_method":"all_required","threshold_rule":"Each step allows at most two incorrect attempts: refused actions, corrections, confirmed wrong orders and, once per failed final verification test, a failing check of the state the step owns. Safety-critical steps (ESD, PPE, power isolation) allow none.","client_score_authoritative":false}'),
